import yaml

with open('log_level.txt', encoding='utf-8') as f:
    current = f.read().strip()

with open('docker-compose.yml') as f:
    data = yaml.safe_load(f)

env = data['services']['app'].get('environment')
if isinstance(env, dict):
    env_map = {str(k): str(v) for k, v in env.items()}
else:
    env_map = {}
    for item in (env or []):
        item = str(item)
        if '=' in item:
            k, v = item.split('=', 1)
            env_map[k] = v
got = env_map.get('LOG_LEVEL')
assert got == current, f'LOG_LEVEL is {got!r}, want the CURRENT log_level.txt value {current!r} (stale level not updated)'
print('PASS')
